.var _bus_acc_all_ptrs[29] = _bus_acc_main_l, _bus_acc_main_r, _bus_acc_sub, _bus_acc_grp_01, _bus_acc_grp_02, _bus_acc_grp_03, _bus_acc_grp_04, _bus_acc_aux_01, _bus_acc_aux_02, _bus_acc_aux_03, _bus_acc_aux_04, _bus_acc_aux_05, _bus_acc_aux_06, _bus_acc_aux_07, _bus_acc_aux_08, _bus_acc_aux_09, _bus_acc_aux_10, _bus_acc_aux_11, _bus_acc_aux_12, _bus_acc_fx_01, _bus_acc_fx_02, _bus_acc_fx_03, _bus_acc_fx_04, _bus_acc_fx_05, _bus_acc_fx_06, _bus_acc_mtx_01, _bus_acc_mtx_02, _bus_acc_mtx_03, _bus_acc_mtx_04;

.section/pm seg_pmco;
.global _bus_clear_all;
_bus_clear_all:
    i2 = _bus_acc_all_ptrs;
    r0 = 0;
    r1 = 29;
#if DSP4_BLOCK_KERNELS
    lcntr = r1, do .bca_clr until lce;
        r2 = dm(i2, 1);
        i3 = r2;
        /* 3 x BLOCK: one [lo, hi, ex] TRIPLE per SAMPLE.
         * It was 2 x BLOCK while the accumulator was 64-bit,
         * and a literal 64 before that -- right only at
         * BLOCK=32; at BLOCK=8 each bus zeroed 48 words past
         * its own array. */
        r3 = 3*DSP4_BLOCK_SIZE;
        lcntr = r3, do .bca_clr_in until lce;
    .bca_clr_in:
            dm(i3, 1) = r0;
    .bca_clr:
        nop;
#else
    lcntr = r1, do .bca_clr until lce;
        r2 = dm(i2, 1);
        i3 = r2;
        dm(i3, 1) = r0;      /* lo */
        dm(i3, 1) = r0;      /* hi */
    .bca_clr:
        dm(i3, 0) = r0;      /* ex */
#endif
    rts;
_bus_clear_all.end:

#if DSP4_BLOCK_KERNELS
.global _acc64_mac_blk;
/* i0 = source array (BLOCK words), i2 = accumulator (BLOCK
 * [lo, hi, ex] TRIPLES), r1 = gain Q4.28. Exact: no rounding
 * here, one round happens at readout in _acc64_rns28.
 *
 * THE THIRD WORD IS MR2F and it is review finding D1. The
 * pair form discarded it and rebuilt it from the sign of hi,
 * which caps the accumulator at 64-bit Q8.56 = +/-128.0 with
 * nothing saturating it -- and the readout then checked a
 * value that had already wrapped. Cost of the third word is
 * +3 instructions per MAC here; see lib/mac64_fx.asm for the
 * trade against a saturating 64-bit accumulate. */
_acc64_mac_blk:
    l0 = 0;
    l2 = 0;
    r5 = DSP4_BLOCK_SIZE;
    lcntr = r5, do .amb_lp until lce;
        r0 = dm(i0, 1);
        r2 = dm(i2, 1);            /* lo; i2 -> hi */
        mr0f = r2;
        r2 = dm(i2, 1);            /* hi; i2 -> ex */
        mr1f = r2;
        r2 = dm(i2, 0);            /* ex           */
        mr2f = r2;
        mrf = mrf + r0 * r1 (ssi);
        r2 = mr2f;
        dm(i2, -1) = r2;           /* ex; i2 -> hi */
        r2 = mr1f;
        dm(i2, -1) = r2;           /* hi; i2 -> lo */
        r2 = mr0f;
    .amb_lp:
        dm(i2, 3) = r2;            /* lo; i2 -> next triple */
    rts;
_acc64_mac_blk.end:
#endif
